parameters.jsCode:
// Compare ce que l'IA a lu avec le catalogue et la liste des clients.
// Rien n'est deviné : au moindre doute, la commande part en alerte.
const R = $('Réglages').item.json;
const mail = R;
const catalogue = $('Charger le catalogue').all().map(i => i.json).filter(p => p.ref);
const clients = $('Charger les clients').all().map(i => i.json).filter(c => c.id_client);
const dejaSaisies = $('Charger les commandes déjà saisies').all().map(i => i.json).filter(c => c.n_commande);

// 1. La réponse de l'IA
let lu;
try {
  const brut = $json.choices[0].message.content.replace(/```json|```/g, '').trim();
  lu = JSON.parse(brut);
} catch (e) {
  lu = { client_id: null, client_nom_lu: '?', date_livraison_souhaitee: null, lignes: [], doute: true,
         remarque: "L'IA n'a pas réussi à lire cette commande." };
}

const anomalies = [];

// 2. Le client
const adresseExpediteur = (mail.from?.value?.[0]?.address || '').toLowerCase();
const client = clients.find(c => c.id_client === lu.client_id)
  || clients.find(c => (c.email || '').toLowerCase() === adresseExpediteur);
if (!client) anomalies.push(`Client inconnu : « ${lu.client_nom_lu} » n'est pas dans la liste des clients.`);

// 3. Les produits et les quantités
const lignes = [];
if (!lu.lignes || lu.lignes.length === 0) anomalies.push("Aucun produit trouvé dans la commande.");
for (const l of (lu.lignes || [])) {
  const produit = catalogue.find(p => p.ref === l.ref);
  const q = Number(l.quantite_cartons);
  if (!produit) {
    anomalies.push(`Produit inconnu : « ${l.designation_lue} » (quantité ${l.quantite_cartons}) n'est pas au catalogue.`);
    continue;
  }
  if (!Number.isInteger(q) || q <= 0 || q > R.quantite_max_par_produit) {
    anomalies.push(`Quantité bizarre : ${l.quantite_cartons} cartons de ${produit.produit}.`);
  }
  lignes.push({ produit, quantite: q });
}

// 4. La date de livraison
const aujourdhui = $now.toFormat('yyyy-MM-dd');
const dateLivraison = lu.date_livraison_souhaitee || '';
if (dateLivraison && dateLivraison < aujourdhui) anomalies.push(`Date de livraison déjà passée : ${dateLivraison}.`);

// 5. Le doute de l'IA, et le mail déjà traité
if (lu.doute) anomalies.push(`L'IA a un doute : ${lu.remarque}`);
if (dejaSaisies.some(c => c.id_mail === mail.id)) anomalies.push("Ce mail a déjà été saisi dans le tableau.");

// 6. Le numéro de commande : le suivant dans le tableau
const numeros = dejaSaisies.map(c => parseInt(String(c.n_commande).replace(/\D/g, ''), 10)).filter(n => !isNaN(n));
const numero = Math.max(R.premier_numero_commande - 1, ...numeros) + 1 + $itemIndex;
const n_commande = `CMD-${numero}`;

const fr = d => d ? DateTime.fromISO(d).setLocale('fr').toFormat('cccc d MMMM') : '';

// Ce qu'il faut pour l'accusé de réception ou l'alerte
const commande = {
  n_commande,
  id_mail: mail.id,
  objet_mail: mail.subject,
  expediteur: (mail.from || {}).text,
  adresse_expediteur: adresseExpediteur,
  id_client: client ? client.id_client : '',
  client: client ? client.client : lu.client_nom_lu,
  contact: client ? client.contact : '',
  email_client: client ? client.email : '',
  date_reception: aujourdhui,
  date_reception_texte: $now.setLocale('fr').toFormat('d MMMM'),
  date_livraison_souhaitee: dateLivraison,
  date_livraison_texte: dateLivraison ? fr(dateLivraison) : 'non précisée',
  recapitulatif: lignes.map(l => `- ${l.quantite} cartons de ${l.produit.produit} (${l.produit.ref})`).join('\n'),
};

return {
  json: {
    ...commande,
    anomalies,
    ce_que_l_ia_a_lu: (lu.lignes || []).map(l => `- ${l.quantite_cartons} x ${l.designation_lue} (réf. ${l.ref || 'aucune'})`).join('\n'),
    // Une ligne par produit, avec les colonnes du tableau Commandes
    lignes: lignes.map(l => ({
      ...commande,
      ref: l.produit.ref,
      produit: l.produit.produit,
      quantite_cartons: l.quantite,
      prix_ht_carton: l.produit.prix_ht_carton,
      total_ht: Math.round(l.quantite * l.produit.prix_ht_carton * 100) / 100,
      statut: 'À préparer',
    })),
  },
};

